mapper.sql:
WHERE d.company_id = #{companyId}

	AND d.dealer_id = #{dealerId}


	AND d.name LIKE #{nameLike} ESCAPE '\\'


	AND d.contact = #{contact}


	AND d.mobile = #{mobile}


	AND d.province = #{province}


	AND d.city = #{city}


	AND d.area = #{area}


	AND JSON_EXTRACT(d.split_ledger_info, '$.adapay_fee_mode') = #{adapayFeeMode}


	AND d.created >= #{timeStart} AND d.created <= #{timeEnd}




		AND (m.audit_state IN ('B','C','D') OR m.audit_state IS NULL)


		AND m.audit_state IN ('A','0')


		AND m.audit_state = 'E'
